// ── HELPERS ─────────────────────────────────────────
const wc = n => n===1?"obor":n<5?"obory":"oborů";

function Wrap({children, noPad}) {
  return (
    <div style={{maxWidth:400,margin:"0 auto",background:S.bg,minHeight:"100vh",paddingBottom:noPad?0:40,fontFamily:"system-ui,sans-serif"}}>
      <style>{GLOBAL_CSS}</style>
      {children}
    </div>
  );
}
function BackBtn({onClick}) {
  return <button onClick={onClick} style={{background:S.card,border:`1px solid ${S.border}`,borderRadius:20,padding:"6px 14px",fontSize:12,color:S.muted,cursor:"pointer",fontWeight:700}}>← Zpět</button>;
}
function BigBtn({onClick,disabled,children,danger}) {
  return <button onClick={disabled?undefined:onClick} style={{width:"100%",padding:15,border:"none",borderRadius:12,fontSize:15,fontWeight:800,cursor:disabled?"default":"pointer",background:disabled?"#22222e":danger?S.red:S.yellow,color:disabled?"#555":danger?"#fff":"#000",fontFamily:"system-ui,sans-serif"}}>{children}</button>;
}
function IndRow({ind,picked,onToggle}) {
  return (
    <div onClick={()=>onToggle(ind.id)} style={{display:"flex",alignItems:"center",gap:12,padding:"11px 14px",borderRadius:12,cursor:"pointer",marginBottom:8,background:picked?"#1E1A00":S.card,border:`${picked?2:1.5}px solid ${picked?S.yellow:S.border}`}}>
      <span style={{fontSize:20,width:28,textAlign:"center",flexShrink:0}}>{ind.e}</span>
      <div style={{flex:1}}><div style={{fontSize:14,fontWeight:700,color:S.white}}>{ind.n}</div><div style={{fontSize:11,color:S.muted,marginTop:2}}>{ind.d}</div></div>
      <span style={{fontSize:14,color:S.yellow,opacity:picked?1:0}}>✓</span>
    </div>
  );
}

// ── ANIMATED AVATAR ──────────────────────────────────
function AnimAvatar({trainer, isTalking, size=200, style={}}) {
  const anim = isTalking ? "talking 0.55s ease-in-out infinite" : "idle 3s ease-in-out infinite";
  return (
    <img
      src={AV[trainer.avatar]}
      alt={trainer.name}
      style={{
        width:size, height:"auto", objectFit:"contain", objectPosition:"bottom",
        animation:anim, transformOrigin:"bottom center",
        filter:"drop-shadow(0 8px 24px rgba(0,0,0,.5))",
        ...style,
      }}
    />
  );
}

// ── SCREEN: ONBOARDING ───────────────────────────────
function Onboarding({onDone}) {
  const [step, setStep] = useState(0); // 0=industry, 1=trainer
  const [sel, setSel] = useState({});
  const [trainer, setTrainer] = useState(null);
  const n = Object.keys(sel).length;
  const toggle = id => setSel(s=>{ const x={...s}; x[id]?delete x[id]:(x[id]=true); return x; });

  if(step===0) return (
    <Wrap>
      <div style={{padding:"28px 16px 12px",textAlign:"center"}}>
        <div style={{fontSize:38,marginBottom:10}}>💼</div>
        <div style={{fontSize:22,fontWeight:900,color:S.white,lineHeight:1.3,marginBottom:8}}>
          Vítej v <span style={{color:S.yellow}}>Sales Trenér AI</span>
        </div>
        <div style={{fontSize:13,color:S.muted,lineHeight:1.65}}>V jakém oboru prodáváš?</div>
      </div>
      <div style={{padding:"4px 16px 12px",fontSize:11,fontWeight:800,color:S.muted,textTransform:"uppercase",letterSpacing:".08em"}}>🏭 Vyber obor (klidně víc)</div>
      <div style={{padding:"0 16px"}}>{INDS.map(i=><IndRow key={i.id} ind={i} picked={!!sel[i.id]} onToggle={toggle}/>)}</div>
      <div style={{textAlign:"center",padding:"10px 16px 4px",fontSize:13,color:S.muted}}>
        {n===0?"Vyber alespoň jeden obor":<span>Vybráno: <b style={{color:S.yellow}}>{n} {wc(n)}</b> — jedem! 💪</span>}
      </div>
      <div style={{padding:"12px 16px 0"}}><BigBtn disabled={n===0} onClick={()=>setStep(1)}>Pokračovat →</BigBtn></div>
    </Wrap>
  );

  return (
    <Wrap>
      <div style={{padding:"20px 16px 16px",textAlign:"center"}}>
        <div style={{fontSize:11,fontWeight:800,color:S.yellow,letterSpacing:".1em",textTransform:"uppercase",marginBottom:8}}>Krok 2 / 2</div>
        <div style={{fontSize:22,fontWeight:900,color:S.white,lineHeight:1.3,marginBottom:8}}>
          Kdo tě bude <span style={{color:S.yellow}}>trénovat?</span> 💪
        </div>
        <div style={{fontSize:13,color:S.muted}}>Každý trenér má jiný styl.</div>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:10,padding:"0 16px"}}>
        {TRAINERS.map(t=>{
          const isPicked = trainer?.id===t.id;
          return (
            <div key={t.id} onClick={()=>setTrainer(t)} style={{borderRadius:16,overflow:"hidden",border:`${isPicked?2.5:1.5}px solid ${isPicked?S.yellow:S.border}`,background:isPicked?"#1E1A00":S.card,cursor:"pointer",position:"relative"}}>
              <div style={{display:"flex",alignItems:"stretch",minHeight:120}}>
                <div style={{width:100,flexShrink:0,background:`linear-gradient(180deg,${t.color} 0%,#0F0F13 100%)`,display:"flex",alignItems:"flex-end",justifyContent:"center",overflow:"hidden"}}>
                  <img src={AV[t.avatar]} alt={t.name} style={{width:88,objectFit:"contain",objectPosition:"bottom"}}/>
                </div>
                <div style={{flex:1,padding:"12px 12px 12px 10px"}}>
                  <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
                    <div style={{fontSize:17,fontWeight:900,color:S.white}}>{t.name}</div>
                    <span style={{fontSize:9,fontWeight:800,padding:"2px 7px",borderRadius:20,background:`${t.accent}22`,color:t.accent,letterSpacing:".06em"}}>{t.tag}</span>
                  </div>
                  <div style={{fontSize:11,color:t.accent,fontWeight:700,marginBottom:6}}>{t.title}</div>
                  <div style={{fontSize:11,color:S.muted,lineHeight:1.5}}>{t.personality}</div>
                  <div style={{display:"flex",alignItems:"center",gap:5,marginTop:8}}>
                    <span style={{fontSize:10,color:S.muted,fontWeight:700}}>🔊 Hlas OpenAI:</span>
                    <span style={{fontSize:10,fontWeight:800,padding:"2px 7px",borderRadius:20,background:"rgba(255,255,255,.07)",color:"rgba(255,255,255,.6)"}}>{t.voice}</span>
                  </div>
                </div>
                {isPicked&&<div style={{position:"absolute",top:10,right:12,fontSize:16,color:S.yellow}}>✓</div>}
              </div>
              {isPicked&&(
                <div style={{borderTop:`1px solid ${S.border}`,padding:"8px 14px",background:"rgba(255,214,0,.04)"}}>
                  <div style={{fontSize:11,color:"rgba(255,214,0,.8)",fontWeight:700}}>{t.emoji} Styl: {t.style}</div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      <div style={{padding:"18px 16px 0"}}>
        <BigBtn disabled={!trainer} onClick={()=>onDone({industries:sel, trainer})}>
          {trainer?`Jdeme s ${trainer.name}em! 🚀`:"Vyber trenéra"}
        </BigBtn>
      </div>
    </Wrap>
  );
}

// ── BOTTOM NAV ──────────────────────────────────────
function BottomNav({tab, onChange}) {
  const tabs = [
    {id:"home",    icon:"🏠", label:"Domů"},
    {id:"lessons", icon:"📚", label:"Lekce"},
    {id:"profile", icon:"👤", label:"Profil"},
  ];
  return (
    <div style={{position:"sticky",bottom:0,left:0,right:0,background:S.bg,borderTop:`1px solid ${S.border}`,display:"flex",zIndex:10}}>
      {tabs.map(t=>{
        const active = t.id===tab;
        return (
          <div key={t.id} onClick={()=>onChange(t.id)} style={{flex:1,padding:"10px 0 12px",display:"flex",flexDirection:"column",alignItems:"center",gap:3,cursor:"pointer"}}>
            <span style={{fontSize:20}}>{t.icon}</span>
            <span style={{fontSize:10,fontWeight:800,color:active?S.yellow:S.muted,letterSpacing:".04em"}}>{t.label}</span>
            {active&&<div style={{width:18,height:3,borderRadius:2,background:S.yellow,marginTop:1}}/>}
          </div>
        );
      })}
    </div>
  );
}

