// ── SCREEN: SETTINGS ────────────────────────────────
function Settings({profile, onSave, onBack}) {
  const [tmp, setTmp] = useState({...profile.industries});
  const n = Object.keys(tmp).length;
  const toggle = id => setTmp(s=>{ const x={...s}; x[id]?delete x[id]:(x[id]=true); return x; });
  const [trainerTmp, setTrainerTmp] = useState(profile.trainer);

  return (
    <Wrap>
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"16px 16px 20px"}}>
        <BackBtn onClick={onBack}/>
        <div style={{fontSize:18,fontWeight:800,color:S.white}}>Nastavení ⚙️</div>
      </div>
      <div style={{padding:"0 16px 10px",fontSize:11,fontWeight:800,color:S.muted,textTransform:"uppercase",letterSpacing:".08em"}}>🏭 Obor prodeje</div>
      <div style={{padding:"0 16px"}}>{INDS.map(i=><IndRow key={i.id} ind={i} picked={!!tmp[i.id]} onToggle={toggle}/>)}</div>
      <div style={{padding:"16px 16px 10px",fontSize:11,fontWeight:800,color:S.muted,textTransform:"uppercase",letterSpacing:".08em"}}>👤 Trenér</div>
      <div style={{display:"flex",gap:8,padding:"0 16px",marginBottom:20}}>
        {TRAINERS.map(t=>{
          const active = trainerTmp?.id===t.id;
          return (
            <div key={t.id} onClick={()=>setTrainerTmp(t)} style={{flex:1,borderRadius:12,padding:"10px 8px",background:active?t.color:S.card,border:`${active?2:1.5}px solid ${active?t.accent:S.border}`,cursor:"pointer",textAlign:"center"}}>
              <img src={AV[t.avatar]} style={{width:50,height:60,objectFit:"contain",objectPosition:"bottom"}} alt={t.name}/>
              <div style={{fontSize:11,fontWeight:800,color:active?"#fff":S.muted,marginTop:4}}>{t.name}</div>
            </div>
          );
        })}
      </div>
      <div style={{padding:"0 16px"}}>
        <BigBtn disabled={n===0||!trainerTmp} onClick={()=>onSave({industries:tmp,trainer:trainerTmp})}>Uložit změny ✅</BigBtn>
      </div>
    </Wrap>
  );
}

