// ── SCREEN: LESSON ───────────────────────────────────
function LessonScreen({cat, level, trainer, onBack}) {
  const [lessonData, setLessonData] = useState(null);
  const [cardIdx, setCardIdx] = useState(0);
  const [phase, setPhase] = useState("loading"); // loading|intro|card|quiz|result|done
  const [isTalking, setIsTalking] = useState(false);
  const [quizAnswer, setQuizAnswer] = useState(null);
  const [quizCorrect, setQuizCorrect] = useState(null);
  const [score, setScore] = useState(0);
  const [totalQ, setTotalQ] = useState(0);
  const synthRef = useRef(window.speechSynthesis);
  const endedRef = useRef(false);

  useEffect(()=>{
    loadLesson();
    return ()=>{ endedRef.current=true; synthRef.current?.cancel(); };
  },[]);

  const [loadMsg, setLoadMsg] = useState(`${trainer.name} si čte poznámky...`);

  const loadLesson = async ()=>{
    const LOADING_MSGS = [`${trainer.name} si čte poznámky...`,"Připravuju ti to nejlepší...","Skoro tam, vydržíš? 💪"];
    setPhase("loading");
    // Rotuj loading zprávy každé 2s
    let msgIdx = 0;
    const msgInterval = setInterval(()=>{
      msgIdx = (msgIdx + 1) % LOADING_MSGS.length;
      setLoadMsg(LOADING_MSGS[msgIdx]);
    }, 2000);

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          model:"claude-haiku-4-5-20251001",
          max_tokens:900,
          system:`Jsi ${trainer.name}, sales trenér. ${trainer.style} Odpovídáš v češtině, stručně a výstižně.`,
          messages:[{role:"user",content:`Vytvoř rychlou lekci: "${cat.name}", úroveň: ${level.label}.
Vrať POUZE JSON (bez markdown):
{"uvod":"1 věta úvod v hlase trenéra","karty":[{"nadpis":"název","text":"2-3 věty výklad","kviz":{"otazka":"otázka","moznosti":["A) ...","B) ...","C) ..."],"spravna":0}}]}
Přesně 3 karty. Buď konkrétní a praktický.`}]
        })
      });
      clearInterval(msgInterval);
      const data = await res.json();
      let raw = (data.content?.[0]?.text||"{}").replace(/```json|```/g,"").trim();
      const parsed = JSON.parse(raw);
      // Validace
      if (!parsed.karty || !parsed.uvod) throw new Error("Špatný formát");
      setLessonData(parsed);
      setPhase("intro");
      speak(parsed.uvod, ()=>{ if(!endedRef.current) setPhase("card"); });
    } catch(e) {
      clearInterval(msgInterval);
      // Fallback obsah
      setLessonData({
        uvod: trainer.id==="natalie" ? "Žádné výmluvy, jedeme." : trainer.id==="pepa" ? "Hurá, jdeme na to! 🚀" : "Začínáme.",
        karty:[
          {nadpis:"Základ č. 1", text:"Zákazník kupuje řešení svého problému, ne tvůj produkt. Vždy začni otázkou, ne prezentací.", kviz:{otazka:"Co zákazník primárně kupuje?",moznosti:["A) Produkt","B) Řešení problému","C) Cenu"],spravna:1}},
          {nadpis:"Základ č. 2", text:"Důvěra předchází prodeji. Bez vztahu není obchod. Investuj čas do pochopení zákazníka.", kviz:{otazka:"Co předchází každému prodeji?",moznosti:["A) Sleva","B) Prezentace","C) Důvěra"],spravna:2}},
          {nadpis:"Základ č. 3", text:"Námitka není odmítnutí — je to zájem. Zákazník se ptá protože zvažuje. Odpovídej klidně a s daty.", kviz:{otazka:"Co znamená námitka zákazníka?",moznosti:["A) Odmítnutí","B) Zájem a zvažování","C) Konec hovoru"],spravna:1}},
        ]
      });
      setPhase("intro");
    }
  };

  const speak = (text, onDone)=>{
    speakWithOpenAI(text, trainer.id, ()=>setIsTalking(true), ()=>{ setIsTalking(false); onDone&&onDone(); });
  };

  const currentCard = lessonData?.karty?.[cardIdx];

  const handleCardRead = ()=>{
    if(!currentCard) return;
    speak(currentCard.text, ()=>{ if(!endedRef.current) setPhase("quiz"); });
    setPhase("reading");
  };

  const handleQuizAnswer = (idx)=>{
    if(quizAnswer!==null) return;
    setQuizAnswer(idx);
    const correct = idx===currentCard.kviz.spravna;
    setQuizCorrect(correct);
    setTotalQ(q=>q+1);
    if(correct) setScore(s=>s+1);
    const feedback = correct
      ? (trainer.id==="natalie"?"Správně. Pokračujeme.":trainer.id==="pepa"?"Jojo, přesně tak! 🎉":"Správně. Dobrá práce.")
      : (trainer.id==="natalie"?"Špatně. Zapamatuj si to.":trainer.id==="pepa"?"Ouuu, tohle příště dáš! 😅":"Nesprávně. Zkus si to zapamatovat.");
    speak(feedback, ()=>{});
  };

  const handleNext = ()=>{
    synthRef.current?.cancel();
    setIsTalking(false);
    setQuizAnswer(null);
    setQuizCorrect(null);
    if(cardIdx+1 >= (lessonData?.karty?.length||0)){
      setPhase("done");
    } else {
      setCardIdx(i=>i+1);
      setPhase("card");
    }
  };

  const accentColor = trainer.accent;
  const cards = lessonData?.karty||[];

  return (
    <div style={{maxWidth:400,margin:"0 auto",background:`linear-gradient(180deg,${trainer.color}44 0%,${S.bg} 280px)`,minHeight:"100vh",fontFamily:"system-ui,sans-serif",paddingBottom:40}}>
      <style>{GLOBAL_CSS}</style>

      {/* Top bar */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"14px 16px 0"}}>
        <BackBtn onClick={()=>{ synthRef.current?.cancel(); onBack(); }}/>
        <div style={{fontSize:11,fontWeight:800,color:"rgba(255,255,255,.6)",textTransform:"uppercase",letterSpacing:".06em"}}>
          {cat.name} · {level.icon} {level.label}
        </div>
        {phase!=="loading"&&phase!=="done"&&(
          <div style={{fontSize:11,color:S.muted,fontWeight:800}}>{cardIdx+1}/{cards.length}</div>
        )}
      </div>

      {/* Progress bar */}
      {cards.length>0&&phase!=="loading"&&phase!=="done"&&(
        <div style={{height:3,background:"rgba(255,255,255,.1)",margin:"10px 16px 0",borderRadius:2,overflow:"hidden"}}>
          <div style={{height:"100%",background:accentColor,width:`${((cardIdx+(phase==="done"?1:0))/cards.length)*100}%`,transition:"width .4s",borderRadius:2}}/>
        </div>
      )}

      {/* Avatar area — vždy viditelný */}
      <div style={{display:"flex",justifyContent:"center",padding:"16px 0 0",minHeight:220,alignItems:"flex-end",position:"relative"}}>
        <AnimAvatar trainer={trainer} isTalking={isTalking} size={180}/>
      </div>

      {/* Trainer name + stav */}
      <div style={{textAlign:"center",padding:"8px 0 12px",display:"flex",flexDirection:"column",alignItems:"center",gap:4}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <div style={{fontSize:14,fontWeight:800,color:S.white}}>{trainer.name}</div>
          {isTalking&&<span style={{width:7,height:7,borderRadius:"50%",background:accentColor,display:"inline-block",animation:"blink .7s infinite"}}/>}
        </div>
        {phase==="loading"&&(
          <div style={{display:"flex",alignItems:"center",gap:8,fontSize:12,color:S.muted}}>
            <div style={{width:14,height:14,border:`2px solid ${S.border}`,borderTopColor:accentColor,borderRadius:"50%",animation:"spin .7s linear infinite",flexShrink:0}}/>
            {loadMsg}
          </div>
        )}
      </div>

      {/* Content area */}
      <div style={{margin:"0 16px",animation:"fadeIn .3s ease-out"}}>

        {/* INTRO */}
        {phase==="intro"&&(
          <div style={{background:S.card,borderRadius:16,padding:"16px",border:`1px solid ${S.border}`,textAlign:"center"}}>
            <div style={{fontSize:24,marginBottom:10}}>👋</div>
            <div style={{fontSize:13,color:S.white,lineHeight:1.65,marginBottom:14}}>{lessonData?.uvod}</div>
            <button onClick={()=>{ synthRef.current?.cancel(); setPhase("card"); }} style={{padding:"10px 24px",background:accentColor,border:"none",borderRadius:10,fontSize:13,fontWeight:800,cursor:"pointer",color:trainer.id==="natalie"?"#fff":"#000",fontFamily:"system-ui,sans-serif"}}>
              Začít →
            </button>
          </div>
        )}

        {/* CARD */}
        {(phase==="card"||phase==="reading")&&currentCard&&(
          <div style={{background:S.card,borderRadius:16,padding:"16px",border:`1px solid ${S.border}`}}>
            <div style={{fontSize:11,fontWeight:800,color:accentColor,letterSpacing:".08em",textTransform:"uppercase",marginBottom:8}}>
              Kapitola {cardIdx+1} / {cards.length}
            </div>
            <div style={{fontSize:16,fontWeight:800,color:S.white,marginBottom:10}}>{currentCard.nadpis}</div>
            <div style={{fontSize:13,color:"rgba(255,255,255,.85)",lineHeight:1.7,marginBottom:16}}>{currentCard.text}</div>
            {phase==="card"&&(
              <button onClick={handleCardRead} style={{width:"100%",padding:"12px",background:accentColor,border:"none",borderRadius:10,fontSize:13,fontWeight:800,cursor:"pointer",color:trainer.id==="natalie"?"#fff":"#000",fontFamily:"system-ui,sans-serif"}}>
                🔊 Přečíst nahlas
              </button>
            )}
            {phase==="reading"&&(
              <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:8,padding:"8px 0"}}>
                {[0,1,2,3,4].map(i=>(
                  <div key={i} style={{width:4,background:accentColor,borderRadius:3,animation:`waveup ${0.4+i*0.1}s ease-in-out ${i*0.08}s infinite`}}/>
                ))}
                <span style={{fontSize:12,color:S.muted,marginLeft:4}}>{trainer.name} mluví...</span>
              </div>
            )}
          </div>
        )}

        {/* QUIZ */}
        {phase==="quiz"&&currentCard&&(
          <div style={{background:S.card,borderRadius:16,padding:"16px",border:`1px solid ${S.border}`}}>
            <div style={{fontSize:11,fontWeight:800,color:accentColor,letterSpacing:".08em",textTransform:"uppercase",marginBottom:8}}>❓ Kvíz</div>
            <div style={{fontSize:14,fontWeight:700,color:S.white,marginBottom:14,lineHeight:1.5}}>{currentCard.kviz.otazka}</div>
            <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:14}}>
              {currentCard.kviz.moznosti.map((opt,i)=>{
                let bg=S.card, borderColor=S.border, textColor=S.muted;
                if(quizAnswer!==null){
                  if(i===currentCard.kviz.spravna){ bg="#1B5E20"; borderColor=S.green; textColor=S.green; }
                  else if(i===quizAnswer&&!quizCorrect){ bg="#7F0000"; borderColor=S.red; textColor=S.red; }
                } else if(quizAnswer===null){
                  textColor=S.white;
                }
                return (
                  <div key={i} onClick={()=>handleQuizAnswer(i)} style={{padding:"11px 14px",borderRadius:10,border:`1.5px solid ${borderColor}`,background:bg,cursor:quizAnswer===null?"pointer":"default",fontSize:13,fontWeight:700,color:textColor,transition:"all .2s"}}>
                    {opt}
                  </div>
                );
              })}
            </div>
            {quizAnswer!==null&&(
              <button onClick={handleNext} style={{width:"100%",padding:"12px",background:accentColor,border:"none",borderRadius:10,fontSize:13,fontWeight:800,cursor:"pointer",color:trainer.id==="natalie"?"#fff":"#000",fontFamily:"system-ui,sans-serif"}}>
                {cardIdx+1<cards.length?"Další kapitola →":"Dokončit lekci 🎉"}
              </button>
            )}
          </div>
        )}

        {/* DONE */}
        {phase==="done"&&(
          <div style={{background:S.card,borderRadius:16,padding:"20px",border:`1px solid ${S.border}`,textAlign:"center"}}>
            <div style={{fontSize:40,marginBottom:12}}>🏆</div>
            <div style={{fontSize:20,fontWeight:900,color:S.white,marginBottom:6}}>Lekce dokončena!</div>
            <div style={{fontSize:13,color:S.muted,marginBottom:16}}>Skóre: <b style={{color:accentColor}}>{score}/{totalQ}</b> správných odpovědí</div>
            <div style={{fontSize:13,color:"rgba(255,255,255,.8)",lineHeight:1.6,marginBottom:18,padding:"10px 14px",background:"rgba(255,255,255,.05)",borderRadius:10}}>
              {score===totalQ
                ?(trainer.id==="natalie"?"Perfektní. Tak to mám ráda.":trainer.id==="pepa"?"Jsiš mašina! Všechno správně 🎉":"Výborně. Všechno správně.")
                :score>=totalQ/2
                ?(trainer.id==="natalie"?"Slušné. Ale dá se lépe.":trainer.id==="pepa"?"Skoro tam! Zopakuj to znovu 💪":"Dobrá práce. Procvič si slabá místa.")
                :(trainer.id==="natalie"?"Nedostatečné. Zopakuj to.":trainer.id==="pepa"?"Nevadí, zkusíme to znovu! 😄":"Zopakuj si tuto lekci.")}
            </div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>{loadLesson();setCardIdx(0);setScore(0);setTotalQ(0);setQuizAnswer(null);}} style={{flex:1,padding:12,background:S.card,border:`1px solid ${S.border}`,borderRadius:10,fontSize:13,fontWeight:800,color:S.white,cursor:"pointer",fontFamily:"system-ui,sans-serif"}}>
                Zopakovat
              </button>
              <button onClick={onBack} style={{flex:1,padding:12,background:accentColor,border:"none",borderRadius:10,fontSize:13,fontWeight:800,cursor:"pointer",color:trainer.id==="natalie"?"#fff":"#000",fontFamily:"system-ui,sans-serif"}}>
                ← Menu
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ── SCREEN: CALL ─────────────────────────────────────
function CallScreen({scenario, diffId:rawDiffId, onEnd, onBack}) {
  const diffId = rawDiffId==="random"?DIFF_KEYS[Math.floor(Math.random()*4)]:rawDiffId;
  const diff = DIFFS.find(d=>d.id===diffId);
  const persona = PERSONAS[scenario.id][diffId];
  const hints = HINTS[scenario.id]||[];

  const [phase, setPhase] = useState("ringing");
  const [timer, setTimer] = useState(0);
  const [aiText, setAiText] = useState("");
  const [userText, setUserText] = useState("");
  const [micLabel, setMicLabel] = useState("Žádám o povolení mikrofonu...");
  const [hintIdx, setHintIdx] = useState(0);
  const [micError, setMicError] = useState(false);
  const [muted, setMuted] = useState(false);
  const [waveH, setWaveH] = useState(Array(9).fill(5));
  const [typedText, setTypedText] = useState("");

  const messagesRef = useRef([{role:"user",content:"Zahaj hovor — řekni jen 'Haló?' a čekej."}]);
  const transcriptRef = useRef([]);
  const startRef = useRef(null);
  const endedRef = useRef(false);
  const synthRef = useRef(window.speechSynthesis);
  const recogRef = useRef(null);
  const silTimerRef = useRef(null);
  const finalRef = useRef("");
  const streamRef = useRef(null);

  useEffect(()=>{
    const t=setInterval(()=>{ if(startRef.current) setTimer(Math.floor((Date.now()-startRef.current)/1000)); },1000);
    return ()=>clearInterval(t);
  },[]);

  useEffect(()=>{
    let wInt;
    if(phase==="ai_speaking"||phase==="ai_thinking"){
      wInt=setInterval(()=>setWaveH(Array(9).fill(0).map(()=>4+Math.random()*28)),90);
    } else if(phase==="user_turn"){
      wInt=setInterval(()=>setWaveH(Array(9).fill(0).map(()=>3+Math.random()*14)),90);
    } else {
      setWaveH(Array(9).fill(5));
    }
    return ()=>clearInterval(wInt);
  },[phase]);

  useEffect(()=>{
    // Spusť hovor hned — mikrofon vyžádáme až když uživatel klikne
    startRef.current = Date.now();
    const t = setTimeout(()=>{ setPhase("ai_thinking"); doAiTurn(); }, 1400);
    return ()=>{ endedRef.current=true; clearTimeout(t); stopRecog(); synthRef.current?.cancel(); clearTimeout(silTimerRef.current); streamRef.current?.getTracks().forEach(t=>t.stop()); };
  },[]);

  const timerStr=`${Math.floor(timer/60)}:${String(timer%60).padStart(2,"0")}`;

  const doAiTurn = useCallback(async()=>{
    try {
      const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:150,system:persona.sys,messages:messagesRef.current})});
      const d=await r.json();
      const txt=d.content?.[0]?.text||"Haló?";
      messagesRef.current=[...messagesRef.current,{role:"assistant",content:txt}];
      transcriptRef.current=[...transcriptRef.current,{who:"ai",text:txt}];
      setAiText(txt); setPhase("ai_speaking");
      speakText(txt);
    } catch{ if(!endedRef.current) startListening(); }
  },[]);

  const speakText=(text)=>{
    // Zákazník mluví přes Web Speech (AI persona, ne trenér)
    speakWebSpeech(text, "customer").then(()=>{ if(!endedRef.current) startListening(); });
  };

  const startListening=useCallback(async()=>{
    if(endedRef.current) return;
    setPhase("user_turn"); setUserText(""); setAiText(""); finalRef.current=""; setHintIdx(i=>i+1);

    const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SR){ setMicLabel("Tvůj prohlížeč nepodporuje mikrofon — napiš odpověď"); return; }

    // Explicitně vyžádej povolení mikrofonu (funguje i mimo iframe)
    if(!streamRef.current && !micError){
      try {
        const stream = await navigator.mediaDevices.getUserMedia({audio:true});
        streamRef.current = stream;
      } catch(err) {
        setMicError(true);
        if(err.name==="NotAllowedError"){
          setMicLabel("🎙️ Povol mikrofon v adresním řádku prohlížeče");
        } else if(err.name==="NotFoundError"){
          setMicLabel("🎙️ Mikrofon nenalezen — zkontroluj připojení");
        } else {
          setMicLabel("🎙️ Mikrofon nedostupný — napiš odpověď dole");
        }
        return;
      }
    }

    if(micError){ setMicLabel("Napiš odpověď dole"); return; }

    setMicLabel("Poslouchám... mluvte");
    const r=new SR(); r.lang="cs-CZ"; r.continuous=false; r.interimResults=true;
    recogRef.current=r;
    r.onresult=e=>{ clearTimeout(silTimerRef.current); let interim="",final=""; for(let i=0;i<e.results.length;i++){if(e.results[i].isFinal)final+=e.results[i][0].transcript;else interim+=e.results[i][0].transcript;} if(final)finalRef.current=final; setUserText(final||interim); silTimerRef.current=setTimeout(()=>{ const txt=(finalRef.current||interim).trim(); if(txt){setUserText("");submitTurn(txt);} },1500); };
    r.onend=()=>{ const txt=finalRef.current.trim(); if(txt){clearTimeout(silTimerRef.current);setUserText("");submitTurn(txt);}else if(!endedRef.current){setMicLabel("Nic jsem neslyšel — zkuste znovu nebo napište");setTimeout(()=>{if(!endedRef.current)startListening();},800);} };
    r.onerror=e=>{
      if(e.error==="not-allowed"){ setMicError(true); setMicLabel("🎙️ Povol mikrofon v nastavení prohlížeče"); }
      else if(e.error==="no-speech"){ setMicLabel("Nic jsem neslyšel — zkuste znovu"); setTimeout(()=>{if(!endedRef.current)startListening();},600); }
      else if(!endedRef.current){ setTimeout(()=>startListening(),600); }
    };
    try{r.start();}catch(e){ console.warn("STT start failed:", e); setTimeout(()=>startListening(),500); }
  },[micError]);

  const stopRecog=()=>{try{recogRef.current?.stop();}catch{}};

  const submitTurn=(text)=>{
    if(endedRef.current)return; stopRecog(); clearTimeout(silTimerRef.current);
    setUserText(text);
    messagesRef.current=[...messagesRef.current,{role:"user",content:text}];
    transcriptRef.current=[...transcriptRef.current,{who:"user",text}];
    setPhase("ai_thinking"); setMicLabel("Zákazník odpovídá...");
    doAiTurn();
  };

  const handleSend=()=>{ const t=typedText.trim(); if(!t||phase==="ai_thinking"||phase==="ai_speaking")return; setTypedText(""); submitTurn(t); };

  const handleHangup=()=>{
    endedRef.current=true; synthRef.current?.cancel(); stopRecog(); clearTimeout(silTimerRef.current); streamRef.current?.getTracks().forEach(t=>t.stop());
    const dur=startRef.current?Math.floor((Date.now()-startRef.current)/1000):0;
    onEnd(transcriptRef.current,dur,diff,persona);
  };

  const handleMute=()=>{ setMuted(m=>{const next=!m;if(next)stopRecog();else if(phase==="user_turn")startListening();return next;}); };

  const isRing=phase==="ringing";
  const isAI=phase==="ai_speaking"||phase==="ai_thinking";
  const isUser=phase==="user_turn";
  const hint=hints[hintIdx%hints.length];

  const waveColor=isAI?S.blue:isUser?S.green:S.border;
  const delays=[0,.15,.3,.15,0,.15,.3,.15,0];

  return (
    <div style={{maxWidth:400,margin:"0 auto",background:"linear-gradient(180deg,#0a0a14,#0f0f1a)",minHeight:"100vh",display:"flex",flexDirection:"column",fontFamily:"system-ui,sans-serif"}}>
      <style>{GLOBAL_CSS}</style>
      <div style={{padding:"14px 20px 0",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{fontSize:12,color:S.muted}}>{scenario.n}</span>
        <span style={{fontSize:14,fontWeight:800,color:S.white,fontVariantNumeric:"tabular-nums",letterSpacing:1}}>{timerStr}</span>
      </div>
      <div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"20px 24px 10px"}}>
        <div style={{width:100,height:100,borderRadius:"50%",background:persona.bg,border:`3px solid ${isAI?S.blue:isRing?S.yellow:S.green}`,boxShadow:`0 0 0 10px ${isAI?S.blue:isRing?S.yellow:S.green}18`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,fontWeight:900,color:S.white,animation:isRing?"ring 1s ease-in-out infinite":"none",marginBottom:16,transition:"border-color .4s,box-shadow .4s"}}>
          {persona.i}
        </div>
        <div style={{fontSize:22,fontWeight:900,color:S.white,marginBottom:4}}>{persona.n}</div>
        <div style={{fontSize:13,color:S.muted,marginBottom:8}}>{persona.r}</div>
        <span style={{fontSize:11,fontWeight:800,padding:"3px 12px",borderRadius:20,background:`${diff.color}22`,color:diff.color,marginBottom:20}}>{diff.icon} {diff.label}</span>
        <div style={{display:"flex",alignItems:"center",gap:5,height:36,marginBottom:14}}>
          {waveH.map((h,i)=>(<div key={i} style={{width:4,borderRadius:3,background:(isAI||isUser)?waveColor:S.border,height:h,animation:(isAI||isUser)?`waveup ${.4+i*.1}s ease-in-out ${delays[i]}s infinite`:"none",transition:"background .3s"}}/>))}
        </div>
        <div style={{fontSize:13,color:S.muted,marginBottom:12,textAlign:"center"}}>
          {isRing?"Vyzvání...":isAI&&phase==="ai_thinking"?"Zákazník přemýšlí...":isAI?"Zákazník mluví":"Váš tah — mluvte"}
        </div>
        {(aiText||userText)&&(
          <div style={{background:isAI?"rgba(68,138,255,.1)":"rgba(0,230,118,.1)",border:`1px solid ${isAI?S.blue:S.green}33`,borderRadius:14,padding:"9px 14px",fontSize:13,color:isAI?S.white:S.green,textAlign:"center",lineHeight:1.55,maxWidth:300,marginBottom:12}}>
            {isAI?aiText:userText}
          </div>
        )}
        <div style={{display:"flex",alignItems:"center",gap:5,fontSize:11,color:isUser&&!micError?S.green:S.muted,marginBottom:6}}>
          {isUser&&!micError&&<span style={{width:6,height:6,borderRadius:"50%",background:S.green,display:"inline-block",animation:"blink .7s infinite"}}/>}
          {!isRing&&micLabel}
        </div>
        {!isRing&&hint&&(<div style={{background:"#161625",borderRadius:12,padding:"7px 12px",fontSize:11,color:S.muted,textAlign:"center",maxWidth:300}}>💡 {hint}</div>)}
      </div>
      {!isRing&&(
        <div style={{padding:"0 20px 12px",display:"flex",gap:8}}>
          <input value={typedText} onChange={e=>setTypedText(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleSend()} placeholder="Záloha: napiš odpověď..." style={{flex:1,padding:"9px 14px",background:S.card,border:`1.5px solid ${S.border}`,borderRadius:12,fontSize:12,fontWeight:700,color:S.white,fontFamily:"system-ui,sans-serif",outline:"none",boxSizing:"border-box"}}/>
          <button onClick={handleSend} style={{padding:"9px 14px",background:S.blue,border:"none",borderRadius:12,color:S.white,fontSize:13,fontWeight:700,cursor:"pointer"}}>↑</button>
        </div>
      )}
      <div style={{padding:"0 24px 40px"}}>
        <div style={{height:1,background:"rgba(255,255,255,.08)",marginBottom:24}}/>
        <div style={{display:"flex",alignItems:"flex-end",justifyContent:"space-between"}}>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:7}}>
            <button onClick={handleMute} style={{width:58,height:58,borderRadius:"50%",border:"none",cursor:"pointer",background:muted?S.white:"rgba(255,255,255,.15)",display:"flex",alignItems:"center",justifyContent:"center",transition:"background .2s"}}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none">{muted?(<><line x1="2" y1="2" x2="22" y2="22" stroke="#000" strokeWidth="2" strokeLinecap="round"/><path d="M18.89 13.23A7 7 0 0 0 19 12v-1M5.07 5.07A7 7 0 0 0 5 12v1M12 19v2M8 21h8M12 1a4 4 0 0 1 4 4v4" stroke="#000" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></>):(<><path d="M12 1a4 4 0 0 1 4 4v7a4 4 0 0 1-8 0V5a4 4 0 0 1 4-4z" stroke="white" strokeWidth="2" strokeLinecap="round"/><path d="M19 10v2a7 7 0 0 1-14 0v-2M12 19v2M8 21h8" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></>)}</svg>
            </button>
            <span style={{fontSize:11,color:muted?S.white:S.muted,fontWeight:600}}>{muted?"Ztlumeno":"Ztlumit"}</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:7}}>
            <button onClick={handleHangup} style={{width:70,height:70,borderRadius:"50%",border:"none",cursor:"pointer",background:S.red,display:"flex",alignItems:"center",justifyContent:"center",boxShadow:`0 6px 20px ${S.red}55`,transition:"transform .1s"}} onMouseEnter={e=>{e.currentTarget.style.transform="scale(1.05)";}} onMouseLeave={e=>{e.currentTarget.style.transform="scale(1)";}}>
              <svg width="28" height="28" viewBox="0 0 24 24" fill="none"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.79 19.79 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><line x1="3" y1="3" x2="21" y2="21" stroke="white" strokeWidth="2" strokeLinecap="round"/></svg>
            </button>
            <span style={{fontSize:11,color:S.muted,fontWeight:600}}>Zavěsit</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:7}}>
            <button style={{width:58,height:58,borderRadius:"50%",border:"none",cursor:"pointer",background:"rgba(255,255,255,.15)",display:"flex",alignItems:"center",justifyContent:"center"}}>
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07" stroke="white" strokeWidth="2" strokeLinecap="round"/></svg>
            </button>
            <span style={{fontSize:11,color:S.muted,fontWeight:600}}>Reproduktor</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── SCREEN: FEEDBACK ────────────────────────────────
function Feedback({scenario, transcript, duration, diff, persona, trainer, onRetry, onMenu}) {
  const [result, setResult] = useState(null);
  const skills = SKILL_SETS[scenario.id];

  useEffect(()=>{
    if(!transcript.filter(t=>t.who==="user").length){setResult("empty");return;}
    const tx=transcript.map(t=>`${t.who==="ai"?persona.n:"Obchodní zástupce"}: ${t.text}`).join("\n");
    fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:600,
        system:`Jsi sales kouč. Vrať POUZE čistý JSON:\n{"skore":75,"dovednosti":[{"nazev":"${skills[0]}","skore":80},{"nazev":"${skills[1]}","skore":70},{"nazev":"${skills[2]}","skore":85},{"nazev":"${skills[3]}","skore":65}],"pochvala":"1 věta","tip":"1-2 věty"}\nObtížnost: ${diff.label}. Přičti ${diff.bonus} bodů (max 100).`,
        messages:[{role:"user",content:`Scénář: ${scenario.n}\nZákazník: ${persona.n}\n\nPřepis:\n${tx}`}]})})
      .then(r=>r.json())
      .then(d=>{let raw=(d.content?.[0]?.text||"{}").replace(/```json|```/g,"").trim();setResult(JSON.parse(raw));})
      .catch(()=>setResult({skore:72,dovednosti:skills.map((n,i)=>({nazev:n,skore:[75,70,80,60][i]})),pochvala:"Solidní start.",tip:"Přidej konkrétní číslo."}));
  },[]);

  const m=Math.floor(duration/60),s=duration%60;
  const sc=v=>v>=80?[S.green,S.green]:v>=65?[S.yellow,S.yellow]:v>=50?["#FF6D00","#FF6D00"]:[S.pink,S.pink];
  const icons=["💬","🎯","🤝","⚡"];

  return (
    <Wrap>
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"16px 16px 0"}}><BackBtn onClick={onMenu}/></div>
      <div style={{padding:"12px 16px 16px"}}>
        <div style={{fontSize:22,fontWeight:900,color:S.white,marginBottom:4}}>Výsledky 🎯</div>
        <div style={{fontSize:11,color:S.muted}}>{scenario.n} · {diff.label} · {persona.n} · {m}:{String(s).padStart(2,"0")}</div>
      </div>
      {!result&&(<div style={{padding:"48px 16px",textAlign:"center"}}><div style={{fontSize:40,marginBottom:14,animation:"bob .9s ease-in-out infinite alternate"}}>🤖</div><div style={{fontSize:13,fontWeight:800,color:S.muted}}>AI kouč analyzuje hovor...</div></div>)}
      {result==="empty"&&(<div style={{padding:"48px 16px",textAlign:"center"}}><div style={{fontSize:40}}>😅</div><div style={{fontSize:13,fontWeight:800,color:S.muted,marginTop:14}}>Hovor byl moc krátký.</div></div>)}
      {result&&result!=="empty"&&(
        <>
          <div style={{margin:"0 16px 14px",borderRadius:14,padding:20,background:scenario.bg,textAlign:"center"}}>
            <div style={{fontSize:60,fontWeight:900,color:S.white,lineHeight:1}}>{Math.min(result.skore,100)}<span style={{fontSize:18,color:"rgba(255,255,255,.4)"}}>/100</span></div>
            <div style={{fontSize:11,color:"rgba(255,255,255,.8)",fontWeight:800,textTransform:"uppercase",letterSpacing:".08em",marginTop:6}}>
              {result.skore>=88?"Naprosto šlapalo! 🔥":result.skore>=74?"Dobrá práce! 💪":result.skore>=58?"Slušný základ 📈":"Víc tréninku! 💡"}
            </div>
            <div style={{fontSize:18,marginTop:6,letterSpacing:3}}>{result.skore>=88?"★★★★★":result.skore>=74?"★★★★☆":result.skore>=58?"★★★☆☆":"★★☆☆☆"}</div>
            <div style={{display:"inline-flex",gap:4,marginTop:8,fontSize:10,fontWeight:800,padding:"3px 10px",borderRadius:20,background:"rgba(0,0,0,.3)",color:"rgba(255,255,255,.8)"}}>{diff.icon} {diff.label} · +{diff.bonus} XP</div>
          </div>
          <div style={{padding:"0 16px",display:"flex",flexDirection:"column",gap:8,marginBottom:14}}>
            {(result.dovednosti||[]).map((d,i)=>{const[col]=sc(Math.min(d.skore,100));return(
              <div key={i} style={{background:S.card,borderRadius:12,padding:"11px 13px"}}>
                <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:7}}>
                  <div style={{display:"flex",alignItems:"center",gap:6}}><span style={{fontSize:13}}>{icons[i]}</span><span style={{fontSize:12,fontWeight:900,color:S.white}}>{d.nazev}</span></div>
                  <span style={{fontSize:13,fontWeight:900,color:col}}>{Math.min(d.skore,100)}</span>
                </div>
                <div style={{height:5,borderRadius:3,background:S.border,overflow:"hidden"}}><div style={{height:"100%",borderRadius:3,background:col,width:`${Math.min(d.skore,100)}%`,transition:"width 1.2s cubic-bezier(.16,1,.3,1)"}}/></div>
              </div>
            );})}
          </div>
          <div style={{margin:"0 16px 16px",background:S.card,borderRadius:14,padding:13,borderLeft:`4px solid ${S.yellow}`}}>
            <div style={{fontSize:10,fontWeight:900,color:S.yellow,letterSpacing:".1em",textTransform:"uppercase",marginBottom:7}}>✅ Co šlo dobře</div>
            <div style={{fontSize:13,color:S.white,lineHeight:1.65}}>{result.pochvala}</div>
            <div style={{height:1,background:S.border,margin:"10px 0"}}/>
            <div style={{fontSize:10,fontWeight:900,color:S.muted,letterSpacing:".1em",textTransform:"uppercase",marginBottom:6}}>💡 Tip ke zlepšení</div>
            <div style={{fontSize:13,color:S.white,lineHeight:1.65}}>{result.tip}</div>
          </div>
        </>
      )}
      <div style={{display:"flex",gap:8,padding:"0 16px"}}>
        <button onClick={onMenu} style={{padding:"13px 16px",background:S.card,color:S.white,border:"none",borderRadius:12,fontSize:13,fontWeight:800,cursor:"pointer"}}>← Menu</button>
        <button onClick={onRetry} style={{flex:1,padding:13,background:S.yellow,color:"#000",border:"none",borderRadius:12,fontSize:13,fontWeight:800,cursor:"pointer"}}>Zkusit znovu 🔁</button>
      </div>
    </Wrap>
  );
}

// ── ROOT ─────────────────────────────────────────────
export default function App() {
  const [screen, setScreen] = useState("onboarding");
  const [profile, setProfile] = useState({industries:{},trainer:null,level:"beginner"});
  const [scenario, setScenario] = useState(null);
  const [callState, setCallState] = useState(null);
  const [lessonCtx, setLessonCtx] = useState(null);

  const nav = (to, payload) => {
    if(to==="setLevel") { setProfile(p=>({...p,level:payload})); return; }
    if(to==="lesson") { setLessonCtx(payload); setScreen("lesson"); return; }
    if(to==="diff") { setScenario(payload); setScreen("diff"); return; }
  };

  if(screen==="onboarding") return <Onboarding onDone={data=>{ setProfile(p=>({...p,...data})); setScreen("main"); }}/>;
  if(screen==="main") return <Main profile={profile} onNav={nav} onSettings={()=>setScreen("settings")}/>;
  if(screen==="settings") return <Settings profile={profile} onSave={data=>{ setProfile(p=>({...p,...data})); setScreen("main"); }} onBack={()=>setScreen("main")}/>;
  if(screen==="lesson") return <LessonScreen cat={lessonCtx.cat} level={lessonCtx.level} trainer={profile.trainer} onBack={()=>setScreen("main")}/>;
  if(screen==="diff") return <DiffPicker scenario={scenario} onStart={d=>{ setCallState({diffId:d}); setScreen("call"); }} onBack={()=>setScreen("main")}/>;
  if(screen==="call") return <CallScreen key={Date.now()} scenario={scenario} diffId={callState.diffId} onEnd={(tx,dur,diff,persona)=>{ setCallState({tx,dur,diff,persona}); setScreen("feedback"); }} onBack={()=>setScreen("diff")}/>;
  if(screen==="feedback") return <Feedback scenario={scenario} transcript={callState.tx} duration={callState.dur} diff={callState.diff} persona={callState.persona} trainer={profile.trainer} onRetry={()=>{ setCallState({diffId:callState.diff.id}); setScreen("call"); }} onMenu={()=>setScreen("main")}/>;
  return null;
}
